// Cart total in yen. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once,
// after the customer's discount.
//
// Rounding:
// - with a customer discount, fractions of a yen are dropped (floor);
// - without one (discount = 0), the total is unchanged from before: half a yen
//   rounds up. Wholesale invoices (src/invoice.js, #7) depend on that.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  return discount === 0 ? Math.round(discounted) : floorYen(discounted);
}

// Floor to whole yen. Float noise is snapped away first, so that e.g.
// 90 * (1 - 0.3) = 62.99999999999999 gives 63, not 62.
function floorYen(amount) {
  return Math.floor(Math.round(amount * 1e6) / 1e6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
