// #12: the customer's discount is applied once, then the bulk discount once.
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10,000 * 0.9 * 0.95
});

test('nine lines get no bulk discount', () => {
  const lines = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8100);
});

test('a discounted total drops fractions of a yen', () => {
  assert.equal(total([{ price: 999, qty: 1 }], 0.1), 899); // 899.1
  assert.equal(total([{ price: 995, qty: 1 }], 0.1), 895); // 895.5
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines, 0.1), 94); // 110 * 0.9 * 0.95 = 94.05
  assert.equal(total([...lines.slice(1), { price: 21, qty: 1 }], 0.1), 102); // 120 * 0.855 = 102.6
});

test('flooring is not thrown off by float noise', () => {
  assert.equal(total([{ price: 90, qty: 1 }], 0.3), 63); // 90 * 0.7 = 62.99999999999999 in floats
});
